SELECT prg.PRO_ID , prg.PRO_NM , prg.MIN_START_DT as prg_start_dt , prg.REG_ID as req_id , hst.MSG_TP , Sum(hst.send_cnt) AS total_cnt , SUM(CAST((cd.cd_desc * hst.send_cnt) AS DECIMAL(12,1))) AS total_cost , team.LIST_NM as team_nm FROM ( SELECT hst.pro_id AS pro_id FROM tblmire_send_hst AS hst LEFT JOIN tblmicp_program AS prg ON prg.PRO_ID = hst.PRO_ID LEFT JOIN tblmicp_campaign AS camp ON camp.PRO_ID = hst.PRO_ID AND camp.seq = hst.camp_id LEFT JOIN tblmi_set_lst AS team ON team.LIST_TP_ID = 'CH02' AND team.LIST_DT_ID = 'TEAM01' AND team.LIST_VAL = camp.TEAM_CD AND team.USR_GRP_CD = camp.USR_GRP_CD
hst.send_rst = '0' AND hst.usr_grp_cd = #{usr_grp_cd}
AND prg.pro_nm like concat('%', #{pro_nm}, '%')
AND team.LIST_NM like concat('%', #{team_nm}, '%')
AND hst.send_req_day >= #{start_dt}
AND hst.send_req_day <= #{end_dt}
AND hst.send_req_day >= #{monthly_dt} and hst.send_req_day < DATE_ADD(LAST_DAY(#{monthly_dt}), INTERVAL 1 DAY)
GROUP BY prg.pro_id ORDER BY hst.send_req_day,hst.pro_id
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}
) as T INNER JOIN tblmire_send_hst AS hst ON hst.pro_id = T.pro_id LEFT JOIN tblmicp_program AS prg ON prg.PRO_ID = hst.PRO_ID LEFT JOIN tblmi_comm_cd AS cd ON cd.grp_id = 'API_PRICE' AND cd.cd_id = hst.usr_grp_cd AND cd.cd_val = hst.msg_tp LEFT JOIN tblmicp_campaign AS camp ON camp.PRO_ID = hst.PRO_ID AND camp.seq = hst.camp_id LEFT JOIN tblmi_set_lst AS team ON team.LIST_TP_ID = 'CH05' AND team.LIST_DT_ID = 'TEAM01' AND team.LIST_VAL = camp.TEAM_CD AND team.USR_GRP_CD = camp.USR_GRP_CD
hst.send_rst = '0' AND hst.usr_grp_cd = #{usr_grp_cd}
AND prg.pro_nm like concat('%', #{pro_nm}, '%')
AND team.LIST_NM like concat('%', #{team_nm}, '%')
AND hst.send_req_day >= #{start_dt}
AND hst.send_req_day <= #{end_dt}
AND hst.send_req_day >= #{monthly_dt} and hst.send_req_day < DATE_ADD(LAST_DAY(#{monthly_dt}), INTERVAL 1 DAY)
GROUP BY prg.pro_id, hst.msg_tp

SELECT COUNT(DISTINCT hst.pro_id) FROM tblmire_send_hst AS hst LEFT JOIN tblmicp_program AS prg ON prg.PRO_ID = hst.PRO_ID LEFT JOIN tblmicp_campaign AS camp ON camp.PRO_ID = hst.PRO_ID AND camp.seq = hst.camp_id LEFT JOIN tblmi_set_lst AS team ON team.LIST_TP_ID = 'CH05' AND team.LIST_DT_ID = 'TEAM01' AND team.LIST_VAL = camp.TEAM_CD AND team.USR_GRP_CD = camp.USR_GRP_CD
